<?php
require __DIR__.'/../admin.php';if(!admin_can('sale')){http_response_code(403);exit('Permission denied.');}$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$actor=sc_admin_guard('sale','update',$_POST);$id=filter_var($_POST['order_id']??0,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid order.');$action=$_POST['action']??'';if($action==='cancel'){sc_stock_cancel($id,$actor['id']);$notice='Order cancelled; deducted stock restored once.';}elseif(in_array($action,['ship','deliver','paid'],true)){$sql=match($action){'ship'=>"UPDATE web_orders SET status='shipped' WHERE id=? AND status='placed'",'deliver'=>"UPDATE web_orders SET status='delivered' WHERE id=? AND status='shipped'",'paid'=>"UPDATE web_orders SET payment_status='paid' WHERE id=? AND status='delivered' AND payment_status='unpaid'"};$stmt=sc_query($sql,'i',[$id]);$notice=$stmt->affected_rows?'Order updated.':'This order is not eligible for that action.';}}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not update the order.':$e->getMessage();}}
$q=mb_substr(trim($_GET['q']??''),0,100);$customer=max(0,(int)($_GET['customer']??0));$id=max(0,(int)($_GET['id']??0));$where=' WHERE 1=1';$params=[];$types='';if($customer){$where.=' AND o.online_user_id=?';$params[]=$customer;$types.='i';}if($id){$where.=' AND o.id=?';$params[]=$id;$types.='i';}if($q!==''){$where.=' AND (o.order_number LIKE ? OR u.email LIKE ? OR o.status LIKE ?)';$needle='%'.addcslashes($q,'%_\\').'%';array_push($params,$needle,$needle,$needle);$types.='sss';}$total=(int)sc_query('SELECT COUNT(*) n FROM web_orders o JOIN online_users u ON u.id=o.online_user_id'.$where,$types,$params)->get_result()->fetch_assoc()['n'];$page=min(max(1,(int)($_GET['p']??1)),max(1,(int)ceil($total/25)));$orders=sc_query('SELECT o.*,u.email FROM web_orders o JOIN online_users u ON u.id=o.online_user_id'.$where.' ORDER BY o.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$types,$params)->get_result();$stats=sc_query("SELECT COUNT(*) total,COALESCE(SUM(status='placed'),0) placed,COALESCE(SUM(status='delivered'),0) delivered,COALESCE(SUM(CASE WHEN status<>'cancelled' AND payment_status='unpaid' THEN total ELSE 0 END),0) pending FROM web_orders")->get_result()->fetch_assoc();admin_console_open('Online Orders');
?>
<div class="row my-3"><?php foreach(['Orders'=>$stats['total'],'Awaiting dispatch'=>$stats['placed'],'Delivered'=>$stats['delivered'],'Unpaid value'=>sc_money((int)round($stats['pending']*100))] as $label=>$value): ?><div class="col-sm-6 col-xl-3"><div class="card p-3 mb-3"><small><?= $label ?></small><strong class="h4 mt-2"><?= sc_e($value) ?></strong></div></div><?php endforeach; ?></div><?php if($notice): ?><p class="alert alert-success" role="status"><?= sc_e($notice) ?></p><?php endif; ?><?php if($error): ?><p class="alert alert-danger" role="alert"><?= sc_e($error) ?></p><?php endif; ?><form method="get" class="sc-list-tools"><label>Search orders<input name="q" type="search" value="<?= sc_e($q) ?>" placeholder="Order number, email or status"></label><?php if($customer): ?><input type="hidden" name="customer" value="<?= $customer ?>"><?php endif; ?><button class="btn btn-primary">Search</button><a href="./">All orders</a><a href="../online-users/">Online users</a></form>
<?php if(!$total): ?><p>No orders match this view.</p><?php endif; ?><?php while($o=$orders->fetch_assoc()):$delivery=json_decode($o['delivery'],true)?:[];$items=sc_query('SELECT * FROM web_order_items WHERE order_id=?','i',[$o['id']])->get_result(); ?><details class="card p-4 mb-3" <?= $id?'open':'' ?>><summary><strong><?= sc_e($o['order_number']) ?></strong> | <?= sc_e($o['status']) ?> | <?= sc_money((int)round($o['total']*100)) ?></summary><p class="mt-3"><a href="../online-users/?id=<?= (int)$o['online_user_id'] ?>&view"><?= sc_e($o['email']) ?></a> | <?= sc_e($o['created_at']) ?></p><p><?= sc_e(implode(', ',array_filter([$delivery['full_name']??'',$delivery['phone']??'',$delivery['address']??'',$delivery['city']??'',$delivery['state']??'',$delivery['pin']??'']))) ?></p><div class="table-responsive"><table class="table" data-info="ignore-dt"><thead><tr><th>Product</th><th>Quantity</th><th>Line total</th></tr></thead><tbody><?php while($i=$items->fetch_assoc()): ?><tr><td><?= sc_e($i['product_name']) ?></td><td><?= (int)$i['quantity'] ?></td><td><?= sc_money((int)round($i['line_total']*100)) ?></td></tr><?php endwhile; ?></tbody></table></div><p>Tax <?= sc_money((int)round($o['tax']*100)) ?> | Total <?= sc_money((int)round($o['total']*100)) ?> | Cash on delivery | <?= sc_e($o['payment_status']) ?></p><?php if(admin_can('sale','update')): ?><form method="post"><?= sc_token() ?><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><?php if($o['status']==='placed'): ?><button class="btn btn-primary" name="action" value="ship">Mark shipped</button><button class="btn btn-outline-danger" name="action" value="cancel">Cancel &amp; restore stock</button><?php elseif($o['status']==='shipped'): ?><button class="btn btn-primary" name="action" value="deliver">Mark delivered</button><?php elseif($o['status']==='delivered' && $o['payment_status']==='unpaid'): ?><button class="btn btn-primary" name="action" value="paid">Confirm COD payment collected</button><?php endif; ?></form><?php endif; ?></details><?php endwhile; ?><nav class="sc-list-pager"><span><?= $total ?> orders | page <?= $page ?></span><?php foreach(['Previous'=>max(1,$page-1),'Next'=>$page+1] as $label=>$p): ?><a href="?<?= sc_e(http_build_query(['q'=>$q,'customer'=>$customer,'p'=>$p])) ?>"><?= $label ?></a><?php endforeach; ?></nav><?php admin_console_close(); ?>
